export const channels={youtube:{name:'유튜브',color:'#64e9c0',icon:'▶',target:1800000},linkedin:{name:'링크드인',color:'#5e9fff',icon:'in',target:1200000},instagram:{name:'인스타그램',color:'#b08cff',icon:'◎',target:1500000}};
export function samples(){return [2025,2026].flatMap(year=>Object.keys(channels).flatMap((channel,c)=>Array.from({length:year===2026?10:12},(_,i)=>({month:`${year}-${String(i+1).padStart(2,'0')}`,channel,impressions:Math.round(([68000,43000,53000][c]+i*[7200,4700,6100][c])*(year===2025?.72:1)*(1+Math.sin(i*1.7+c)*.1)),engagement:Math.round(1800+i*230+c*400),followers:120+i*16+c*23,source:'sample'}))));}
export function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(!quoted&&cell!=='')throw Error('잘못된 CSV 따옴표 형식');else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV 따옴표가 닫히지 않았습니다.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows;}
export function validateRows(rows){const errors=[],records=[];const headers=['월','채널','조회노출','참여','팔로워증가'];if(!rows.length)return {errors:['파일이 비어 있습니다.'],records};const indexes=headers.map(h=>rows[0].indexOf(h));if(indexes.some(i=>i<0))return {errors:['필수 열: '+headers.join(', ')],records};const seen=new Set();rows.slice(1).forEach((row,i)=>{if(!row.some(v=>String(v??'').trim()))return;const [month,name,...nums]=indexes.map(j=>String(row[j]??'').trim());const channel=Object.keys(channels).find(k=>channels[k].name===name);const err=[];if(!/^(202[0-9]|20[3-9][0-9])-(0[1-9]|1[0-2])$/.test(month))err.push('월은 2020~2099의 YYYY-MM');if(!channel)err.push('지원하지 않는 채널');if(nums.some(n=>!/^\d+$/.test(n)||!Number.isSafeInteger(Number(n))))err.push('수치는 0 이상의 안전한 정수');if(channel&&seen.has(month+channel))err.push('파일 내 월·채널 중복');seen.add(month+channel);if(err.length)errors.push(`${i+2}행: ${err.join(' / ')}`);else records.push({month,channel,impressions:+nums[0],engagement:+nums[1],followers:+nums[2],source:'import'});});if(!records.length&&!errors.length)errors.push('실적 행이 없습니다.');return {errors,records};}
export function aggregate(records){return records.reduce((a,r)=>({impressions:a.impressions+r.impressions,engagement:a.engagement+r.engagement,followers:a.followers+r.followers}),{impressions:0,engagement:0,followers:0});}
export function mergeRecords(existing,incoming){const keys=new Set(incoming.map(r=>r.month+r.channel));return existing.filter(r=>!keys.has(r.month+r.channel)).concat(incoming).sort((a,b)=>a.month.localeCompare(b.month));}
export function growth(now,before){return before===0?(now===0?'0.0%':'비교 불가'):`${now>=before?'+':''}${((now-before)/before*100).toFixed(1)}%`;}
